public Link getLink(boolean collapseWhitespace) {
    String anchor = text.toString();
    if (collapseWhitespace) {
        anchor = anchor.replaceAll("\\s+", " ").trim();
    }
    return new Link(type, uri, title, anchor, rel);
}
